{
  "rule": "If the factual description indicates that the defendant established, operated, or maintained a venue or equipment specifically for gambling (e.g., opening a game hall, installing gambling machines, running a casino), the correct charge is “开设赌场罪” (establishing a casino) rather than the broader “组织赌博罪”.",
  "keywords": [
    "开设游戏厅",
    "设置赌博机",
    "经营赌博场所",
    "设立赌博场所",
    "开设赌场"
  ]
}
